17	/*
18	 * KernelHiFloat8CastLut — LUT 查表实现
19	 *
20	 *  castMode          | LUT 每元素指令数 | 优化手段
21	 *  ------------------|----------------|--------------------------------
22	 *  FP16_TO_HIF8      | ~5 条          | 32768-entry 半空间 UB LUT + 符号分离
23	 *  BF16_TO_HIF8      | ~5 条          | 32768-entry 半空间 UB LUT + 符号分离
24	 *  HIF8_TO_FP16      | 1 条           | 256-entry UB LUT 消除分支
25	 *  HIF8_TO_BF16      | 1 条           | 256-entry UB LUT 消除分支
26	 *
27	 * UB 占用（tileLength 由 host 运行时根据平台实际可用 UB 大小计算；
28	 *          maxTile ≥ 32768 时对齐到 32768，否则对齐到 32，上限 65536）：
29	 *   BF16/FP16 encode:  32KB(LUT16) + 1T×2B(inQ) + 1T×1B(outQ)  = 32768 + 3T bytes
30	 *   decode FP16/BF16:   1KB(LUT8)  + 1T×1B(inQ) + 1T×2B(outQ)  =   512 + 3T bytes
31	 *
32	 *   单缓冲：compute 为标量循环，与 MTE 流水重叠收益为 0，
33	 *   故 TQue depth=1 + InitBuffer num=1，释放队列另一半 UB 给 tile。
34	 *
35	 * CopyIn DataCopy 拆分策略（DataCopyParams.blockLen 为 uint16_t，max 65535）：
36	 *   byteCount ≤ 65535           → {1, byteCount}
37	 *   byteCount % 32768 == 0      → {byteCount/32768, 32768}   (全 tile，tileLength 对齐保证整除)
38	 *   byteCount 为偶数（encode tail）→ {2, byteCount/2}         (count ≤ 65535，blockLen ≤ 65535)
39	 *
40	 * 半空间 LUT 原理：
41	 *   BF16/FP16 编码关于符号位对称：encode(-x) = encode(x) | 0x80（当 encode(x)≠0 时）
42	 *   只存正半空间（32768 条量级值），compute 时先剥离符号，查表后再叠加符号位。
43	 *   节省 32KB UB，且 DataCopyPad(32KB) 单次完成（不再需要分两次）。
44	 *
45	 * A2 平台约束说明：
46	 *   Cast<uint32_t, uint16_t> ❌（编译器不支持）→ 无法用 Gather 向量化
47	 *   ShiftLeft/Right uint16_t/uint32_t ❌
48	 *   当前 BF16/FP16 encode 仍为标量循环，但每步只需 ~5 条 UB 查表+位运算指令
49	 */
50	
51	#include "kernel_operator.h"
52	#include "hifloat8_cast_tiling.h"
53	
54	constexpr uint32_t HIF8_KERNEL_SIGN_SHIFT = 7;
55	
56	class KernelHiFloat8CastLut {
57	public:
58	    __aicore__ inline KernelHiFloat8CastLut(AscendC::TPipe *pipe) : pipe_(pipe) {}
59	
60	    __aicore__ inline void Init(
61	        GM_ADDR input, GM_ADDR output, const __gm__ HiFloat8CastTilingData *tiling, GM_ADDR lutGm) {
62	        uint32_t castMode = tiling->castMode;
63	        uint32_t blockIdx = AscendC::GetBlockIdx();
64	
65	        isEncode_ = (castMode <= BF16_TO_HIF8);
66	        inputBytes_ = isEncode_ ? 2u : 1u;
67	        outputBytes_ = isEncode_ ? 1u : 2u;
68	        tileLength_ = tiling->tileLength;
69	
70	        total_ = (blockIdx < tiling->blockNum - 1) ? tiling->numPerCore : tiling->tailNumLastCore;
71	        tileNum_ = (total_ + tileLength_ - 1) / tileLength_;
72	        tailTile_ = static_cast<uint32_t>(total_ - static_cast<uint64_t>(tileLength_) * (tileNum_ - 1));
73	        // tailTile_ > 0 guaranteed: total_ > 0, ceiling division ensures last tile is non-empty
74	
75	        uint64_t offset = static_cast<uint64_t>(blockIdx) * tiling->numPerCore;
76	        inputGm_.SetGlobalBuffer((__gm__ uint8_t *)input + offset * inputBytes_, total_ * inputBytes_);
77	        outputGm_.SetGlobalBuffer((__gm__ uint8_t *)output + offset * outputBytes_, total_ * outputBytes_);
78	        pipe_->InitBuffer(inQueue_, 1, tileLength_ * inputBytes_);
79	        pipe_->InitBuffer(outQueue_, 1, tileLength_ * outputBytes_);
80	
81	        if (isEncode_) {
82	            pipe_->InitBuffer(lut16Buf_, LUT16_SIZE);
83	            AscendC::GlobalTensor<uint8_t> lutGmTensor;
84	            lutGmTensor.SetGlobalBuffer((__gm__ uint8_t *)lutGm, LUT16_SIZE);
85	            auto lutUb = lut16Buf_.Get<uint8_t>();
86	            AscendC::DataCopyParams cp{1, static_cast<uint16_t>(LUT16_SIZE), 0, 0};
87	            AscendC::DataCopyPadParams pp{false, 0, 0, 0};
88	            AscendC::DataCopyPad(lutUb, lutGmTensor[0], cp, pp);
89	        } else {
90	            pipe_->InitBuffer(lut8Buf_, LUT8_SIZE * 2u);
91	            AscendC::GlobalTensor<uint16_t> lutGmTensor;
92	            lutGmTensor.SetGlobalBuffer((__gm__ uint16_t *)lutGm, LUT8_SIZE);
93	            auto lutUb = lut8Buf_.Get<uint16_t>();
94	            AscendC::DataCopyParams cp{1, static_cast<uint16_t>(LUT8_SIZE * 2u), 0, 0};
95	            AscendC::DataCopyPadParams pp{false, 0, 0, 0};
96	            AscendC::DataCopyPad(lutUb, lutGmTensor[0], cp, pp);
97	        }
98	    }
99	
100	    __aicore__ inline void Process() {
101	        for (uint64_t i = 0; i < tileNum_; i++) {
102	            uint32_t count = (i == tileNum_ - 1) ? tailTile_ : tileLength_;
103	            CopyIn(i, count);
104	            Compute(count);
105	            CopyOut(i, count);
106	        }
107	    }
108	
109	private:
110	    // ── 数据搬运 ────────────────────────────────────────────────────────────
111	
112	    __aicore__ inline void CopyIn(uint64_t tileIdx, uint32_t count) {
113	        uint64_t byteOffset = tileIdx * static_cast<uint64_t>(tileLength_) * inputBytes_;
114	        uint32_t byteCount = count * inputBytes_;
115	        auto xLocal = inQueue_.AllocTensor<uint8_t>();
116	        AscendC::DataCopyPadParams padParams{false, 0, 0, 0};
117	        // DataCopyParams.blockLen is uint16_t (max 65535); split large byteCount:
118	        //
119	        //  Case A — byteCount ≤ 65535 : {1, byteCount}
120	        //           covers all decode tiles and small encode tails
121	        //
122	        //  Case B — byteCount % 32768 == 0 : {byteCount/32768, 32768}
123	        //           full tiles when tileLength ∈ {32768, 65536} (tileLength aligned to 32768)
124	        //           e.g. encode tileLength=65536 → byteCount=131072 → {4, 32768}
125	        //               decode tileLength=65536 → byteCount=65536  → {2, 32768}
126	        //
127	        //  Case C — byteCount even, not case B : {2, byteCount/2}
128	        //           encode tail tiles; byteCount=count*2, count ≤ 65535 → byteCount/2 ≤ 65535
129	        AscendC::DataCopyParams cp;
130	        if (byteCount <= 65535u) {
131	            cp = {1, static_cast<uint16_t>(byteCount), 0, 0};
132	        } else if (byteCount % 32768u == 0u) {
133	            cp = {static_cast<uint16_t>(byteCount / 32768u), 32768u, 0, 0};
134	        } else {
135	            cp = {2u, static_cast<uint16_t>(byteCount >> 1), 0, 0};
136	        }
137	        AscendC::DataCopyPad(xLocal, inputGm_[byteOffset], cp, padParams);
138	        inQueue_.EnQue(xLocal);
139	    }
140	
141	    __aicore__ inline void CopyOut(uint64_t tileIdx, uint32_t count) {
142	        uint64_t byteOffset = tileIdx * static_cast<uint64_t>(tileLength_) * outputBytes_;
143	        uint32_t byteCount = count * outputBytes_;
144	        auto yLocal = outQueue_.DeQue<uint8_t>();
145	        AscendC::DataCopyExtParams copyParams{1, byteCount, 0, 0, 0};
146	        AscendC::DataCopyPad(outputGm_[byteOffset], yLocal, copyParams);
147	        outQueue_.FreeTensor(yLocal);
148	    }
149	
150	    // ── 计算分派 ──
151	    __aicore__ inline void Compute(uint32_t count) {
152	        if (isEncode_) {
153	            ComputeEncode16(count);
154	        } else {
155	            ComputeDecode(count);
156	        }
157	    }
158	
159	    // ── BF16/FP16 → HiF8（半空间 UB LUT + 符号分离）──
160	    // LUT 只存正半空间量级（32768 条），利用对称性：
161	    //   encode(-x) = encode(x) | 0x80  （当 encode(x) ≠ 0 时）
162	    //   encode(-0) = 0x00              （下溢/零不加符号位）
163	    // 每元素约 5 条指令（AND + GetValue + SHR + compare + OR），
164	    // 节省 32KB UB，且 DataCopyPad 从 2 次合并为 1 次。
165	    __aicore__ inline void ComputeEncode16(uint32_t count) {
166	        auto xLocal = inQueue_.DeQue<uint8_t>();
167	        auto xU16 = xLocal.template ReinterpretCast<uint16_t>();
168	        auto yLocal = outQueue_.AllocTensor<uint8_t>();
169	        auto lut = lut16Buf_.Get<uint8_t>();
170	
171	        for (uint32_t i = 0; i < count; i++) {
172	            uint16_t v = xU16.GetValue(i);
173	            uint8_t sign = static_cast<uint8_t>(v >> 15);
174	            uint8_t mag = lut.GetValue(static_cast<uint32_t>(v & 0x7FFFu));
175	            // 下溢/零时 mag==0，不叠加符号位（保持 0x00）
176	            yLocal.SetValue(i, (mag == 0x00u) ? 0x00u : (mag | (sign << HIF8_KERNEL_SIGN_SHIFT)));
177	        }
178	
179	        outQueue_.EnQue(yLocal);
180	        inQueue_.FreeTensor(xLocal);
181	    }
182	
183	    // ── HiF8 → FP16/BF16（UB LUT 直查，无分支）────────────────────────────
184	    __aicore__ inline void ComputeDecode(uint32_t count) {
185	        auto xLocal = inQueue_.DeQue<uint8_t>();
186	        auto yLocal = outQueue_.AllocTensor<uint8_t>();
187	        auto lut = lut8Buf_.Get<uint16_t>();
188	        auto yU16 = yLocal.template ReinterpretCast<uint16_t>();
189	        for (uint32_t i = 0; i < count; i++) {
190	            yU16.SetValue(i, lut.GetValue(xLocal.GetValue(i)));
191	        }
192	        outQueue_.EnQue(yLocal);
193	        inQueue_.FreeTensor(xLocal);
194	    }
195	
196	private:
197	    AscendC::TPipe *pipe_;
198	
199	    bool isEncode_ = false;
200	    uint32_t inputBytes_ = 0;
201	    uint32_t outputBytes_ = 0;
202	    uint32_t tileLength_ = 0;
203	    uint64_t total_ = 0;
204	    uint64_t tileNum_ = 0;
205	    uint32_t tailTile_ = 0;
206	
207	    AscendC::GlobalTensor<uint8_t> inputGm_;
208	    AscendC::GlobalTensor<uint8_t> outputGm_;
209	
210	    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueue_;
211	    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueue_;
212	
213	    // BF16/FP16 encode UB LUT（32768 × 1B = 32KB，半空间）
214	    AscendC::TBuf<AscendC::TPosition::VECCALC> lut16Buf_;
215	    // decode UB LUT（256 × 2B = 512B，FP16/BF16 输出）
216	    AscendC::TBuf<AscendC::TPosition::VECCALC> lut8Buf_;
217	};
218	
219	extern "C" __global__ __vector__ void hifloat8_cast_kernel_lut(
220	    GM_ADDR input, GM_ADDR output, GM_ADDR tiling, GM_ADDR lutGm) {
221	    AscendC::TPipe pipe;
222	    KernelHiFloat8CastLut op(&pipe);
223	    op.Init(input, output, (__gm__ HiFloat8CastTilingData *)tiling, lutGm);
224	    op.Process();
225	}
