33	namespace {
34	constexpr uint32_t FP16_EXP_BITS = 5;
35	constexpr uint32_t FP16_FRAC_BITS = 10;
36	constexpr uint32_t FP16_EXP_BIAS = 15;
37	
38	constexpr uint32_t BF16_EXP_BITS = 8;
39	constexpr uint32_t BF16_FRAC_BITS = 7;
40	constexpr uint32_t BF16_EXP_BIAS = 127;
41	
42	constexpr uint32_t HIF8_SIGN_SHIFT = 7;
43	constexpr uint32_t HIF8_DENORMAL_EXP_BIAS = 23;
44	constexpr uint8_t HIF8_POSITIVE_MIN_NORMAL = 0x7E;
45	
46	constexpr uint32_t HIF8_DOT_TABLE[16] = {
47	    (0x00 << 24) | (3 << 16) | (0 << 8) | (0 << 4) | 7,
48	    (0x00 << 24) | (3 << 16) | (1 << 8) | (0 << 4) | 7,
49	    (0x08 << 24) | (3 << 16) | (3 << 8) | (1 << 4) | 7,
50	    (0x08 << 24) | (3 << 16) | (3 << 8) | (1 << 4) | 7,
51	    (0x18 << 24) | (3 << 16) | (4 << 8) | (2 << 4) | 7,
52	    (0x18 << 24) | (3 << 16) | (4 << 8) | (2 << 4) | 7,
53	    (0x18 << 24) | (3 << 16) | (4 << 8) | (2 << 4) | 7,
54	    (0x18 << 24) | (3 << 16) | (4 << 8) | (2 << 4) | 7,
55	    (0x1c << 24) | (2 << 16) | (4 << 8) | (3 << 4) | 3,
56	    (0x1c << 24) | (2 << 16) | (4 << 8) | (3 << 4) | 3,
57	    (0x1c << 24) | (2 << 16) | (4 << 8) | (3 << 4) | 3,
58	    (0x1c << 24) | (2 << 16) | (4 << 8) | (3 << 4) | 3,
59	    (0x1e << 24) | (1 << 16) | (4 << 8) | (4 << 4) | 1,
60	    (0x1e << 24) | (1 << 16) | (4 << 8) | (4 << 4) | 1,
61	    (0x1e << 24) | (1 << 16) | (4 << 8) | (4 << 4) | 1,
62	    (0x1e << 24) | (1 << 16) | (4 << 8) | (4 << 4) | 1,
63	};
64	} // namespace
65	
66	static uint32_t HostHif8ToFpBits(uint8_t inData, uint32_t expBits, uint32_t fracBits, uint32_t expBias) {
67	    if (inData == 0) {
68	        return 0;
69	    }
70	
71	    uint32_t expMax = (1u << expBits) - 1;
72	    if (inData == 0x80)
73	        return (expMax << fracBits) | ((1u << fracBits) - 1);
74	    if (inData == 0x6F)
75	        return expMax << fracBits;
76	    if (inData == 0xEF)
77	        return (1u << 15) | (expMax << fracBits); // 15: FP16/BF16符号位位置
78	
79	    uint8_t dot = (inData & 0x78) >> 3;
80	    uint32_t info = HIF8_DOT_TABLE[dot];
81	
82	    uint8_t expMask = (info >> 24) & 0xFF;
83	    uint8_t fracHiF8Bits = (info >> 16) & 0xFF;
84	    uint8_t expSignShift = (info >> 8) & 0xFF;
85	    uint8_t expHiF8Bits = (info >> 4) & 0x0F;
86	    uint8_t fracMask = info & 0x0F;
87	
88	    uint32_t expHiF8 = (inData & expMask) >> fracHiF8Bits;
89	    uint32_t signExp = (inData >> expSignShift) & 0x01;
90	    uint32_t fracFpN = inData & fracMask;
91	    uint32_t expFpN = 0;
92	    uint32_t sign = inData >> HIF8_SIGN_SHIFT;
93	
94	    if (expSignShift == 0) {
95	        int32_t biasedExp = static_cast<int32_t>(expBias) - static_cast<int32_t>(HIF8_DENORMAL_EXP_BIAS - fracFpN);
96	        if (biasedExp <= 0) {
97	            int32_t shift = biasedExp - 1 + static_cast<int32_t>(fracBits);
98	            uint32_t mantissa = (shift >= 0) ? (1u << static_cast<uint32_t>(shift)) : 0u;
99	            return (sign << 15) | mantissa; // 15: FP16/BF16符号位位置
100	        }
101	        expFpN = static_cast<uint32_t>(biasedExp);
102	        fracFpN = 0;
103	    } else if (expSignShift == 1) {
104	        expFpN = expBias;
105	    } else {
106	        int32_t expNoBias = static_cast<int32_t>((expHiF8 | (1u << (expHiF8Bits - 1))) * (signExp == 1 ? -1 : 1));
107	        int32_t biasedExp = expNoBias + static_cast<int32_t>(expBias);
108	        if (biasedExp <= 0) {
109	            int32_t shift = biasedExp - 1 + static_cast<int32_t>(fracBits) - static_cast<int32_t>(fracHiF8Bits);
110	            uint32_t S = (1u << fracHiF8Bits) | fracFpN;
111	            uint32_t mantissa =
112	                (shift >= 0) ? (S << static_cast<uint32_t>(shift)) : (S >> static_cast<uint32_t>(-shift));
113	            return (sign << 15) | mantissa; // 15: FP16/BF16符号位位置
114	        }
115	        expFpN = static_cast<uint32_t>(biasedExp);
116	    }
117	
118	    return (sign << 15) | (expFpN << fracBits) | (fracFpN << (fracBits - fracHiF8Bits)); // 15: FP16/BF16符号位位置
119	}
120	
121	static at::Tensor BuildLut8Cpu(int64_t castMode) {
122	    bool isFP16 = (castMode == HIF8_TO_FP16);
123	    uint32_t expBits = isFP16 ? FP16_EXP_BITS : BF16_EXP_BITS;
124	    uint32_t fracBits = isFP16 ? FP16_FRAC_BITS : BF16_FRAC_BITS;
125	    uint32_t expBias = isFP16 ? FP16_EXP_BIAS : BF16_EXP_BIAS;
126	
127	    at::Tensor lut = at::empty({LUT8_SIZE}, at::device(at::kCPU).dtype(at::kUInt16));
128	    uint16_t *data = lut.data_ptr<uint16_t>();
129	    for (uint32_t i = 0; i < LUT8_SIZE; i++) {
130	        data[i] = static_cast<uint16_t>(HostHif8ToFpBits(static_cast<uint8_t>(i), expBits, fracBits, expBias));
131	    }
132	    return lut;
133	}
134	
135	// ── Host-side LUT helpers ─────────────────────────────────────────────────────
136	// Run on CPU to precompute the 32768-entry encode LUT once per mode.
137	static void HostGetHif8BitsNum(int32_t expNoBias, uint32_t &dotValue, uint32_t &expBitsOut, uint32_t &fracBitsOut) {
138	    int32_t absExp = expNoBias < 0 ? -expNoBias : expNoBias;
139	    if (expNoBias == 0) {
140	        dotValue = 0x01;
141	        expBitsOut = 0;
142	        fracBitsOut = 3; // 3: HiFloat8尾数位数，dotValue=1场景
143	    } else if (absExp == 1) {
144	        dotValue = 0x02;
145	        expBitsOut = 1;
146	        fracBitsOut = 3;                     // 3: HiFloat8尾数位数，dotValue=2场景
147	    } else if (absExp >= 2 && absExp <= 3) { // HiFloat8指数区间[2, 3]
148	        dotValue = 0x04;
149	        expBitsOut = 2;                      // 2: HiFloat8指数位数，dotValue=4场景
150	        fracBitsOut = 3;                     // 3: HiFloat8尾数位数，dotValue=4场景
151	    } else if (absExp >= 4 && absExp <= 7) { // HiFloat8指数区间[4, 7]
152	        dotValue = 0x08;
153	        expBitsOut = 3;                      // 3: HiFloat8指数位数，dotValue=8场景
154	        fracBitsOut = 2;                     // 2: HiFloat8尾数位数，dotValue=8场景
155	    } else {
156	        dotValue = 0x0C;
157	        expBitsOut = 4;  // 4: HiFloat8指数位数，dotValue=0xc场景
158	        fracBitsOut = 1; // 1: HiFloat8尾数位数，dotValue=0xc场景
159	    }
160	}
161	
162	static uint8_t HostFp32MagnitudeToHif8(uint32_t inData) {
163	    uint32_t expFp = (inData >> 23) & 0xFF; // 23: FP32尾数位数
164	    uint32_t fracFp = inData & 0x7FFFFF;
165	    // Host LUT 只编码正数幅值，符号位由 device encode 阶段补回。
166	    if (expFp == 0)
167	        return 0x00;
168	    if (expFp == 255) // 255: FP32指数最大值（全1）
169	        return fracFp > 0 ? 0x80 : 0x6F;
170	
171	    int32_t expNoBias = static_cast<int32_t>(expFp) - 127; // 127: FP32指数偏置
172	    // 超出 HiFloat8 表示范围时，饱和到最大正有限值。
173	    if (expNoBias >= 15) // 15: HiFloat8最大指数
174	        return 0x6E;
175	
176	    // HiFloat8 denormal 区间；过小值归零，边界值保留最小非零编码。
177	    if (expNoBias < -15) {    // 15: HiFloat8最大指数
178	        if (expNoBias < -23)  // 23: FP32尾数位数
179	            return 0x00;
180	        if (expNoBias == -23) // 23: FP32尾数位数
181	            return 0x01;
182	
183	        uint32_t fracHiF8 = static_cast<uint32_t>(HIF8_DENORMAL_EXP_BIAS + expNoBias);
184	        if ((fracFp >> 22) >= 1u) // 22: FP32尾数位数-1
185	            ++fracHiF8;
186	        return fracHiF8 >= 8u ? HIF8_POSITIVE_MIN_NORMAL :
187	                                static_cast<uint8_t>(fracHiF8); // 8: HiFloat8非规格化数最大值
188	    }
189	    uint32_t dotValue = 0;
190	    uint32_t expHiF8Bits = 0;
191	    uint32_t fracHiF8Bits = 0;
192	    HostGetHif8BitsNum(expNoBias, dotValue, expHiF8Bits, fracHiF8Bits);
193	    uint32_t fracShift = 23 - fracHiF8Bits - 1; // 23: FP32尾数位数
194	    uint32_t fractmp = fracFp >> fracShift;
195	    uint32_t fracMax = (1u << (fracHiF8Bits + 1)) - 1;
196	    uint32_t fracHiF8 = 0;
197	    // 多取 1 bit 作为舍入位；尾数溢出时进位到下一个指数段。
198	    if (fractmp == fracMax) {
199	        expNoBias += 1;
200	        HostGetHif8BitsNum(expNoBias, dotValue, expHiF8Bits, fracHiF8Bits);
201	    } else if ((fractmp & 0x01) == 0x01) {
202	        fracHiF8 = (fractmp + 1) >> 1;
203	    } else {
204	        fracHiF8 = fractmp >> 1;
205	    }
206	    if (dotValue == 1)
207	        return static_cast<uint8_t>((dotValue << fracHiF8Bits) | fracHiF8);
208	    int32_t absExpFinal = expNoBias < 0 ? -expNoBias : expNoBias;
209	    uint32_t signExp = expNoBias < 0 ? 1u : 0u;
210	    uint32_t expHiF8 = static_cast<uint32_t>(absExpFinal) - (1u << (expHiF8Bits - 1));
211	    // 3：dot value移动到[6:3]位置，再拼接 dot、指数符号、指数幅值和尾数，得到无数值符号位的 HiFloat8 编码。
212	    return static_cast<uint8_t>(
213	        (dotValue << 3) | (signExp << (expHiF8Bits + fracHiF8Bits - 1)) | (expHiF8 << fracHiF8Bits) | fracHiF8);
214	}
215	
216	// Build 32768-entry encode LUT on CPU for FP16 or BF16.
217	// Positive half only (sign bit stripped): key = absBits = val & 0x7FFF, value = magnitude.
218	// Sign is re-applied in ComputeEncode16.
219	static at::Tensor BuildLut16Cpu(int64_t castMode) {
220	    bool isFP16 = (castMode == FP16_TO_HIF8);
221	    uint32_t expBias = isFP16 ? 15u : 127u;
222	    uint32_t expBitsN = isFP16 ? 5u : 8u;
223	    uint32_t fracBitsN = isFP16 ? 10u : 7u;
224	
225	    at::Tensor lut = at::empty({LUT16_SIZE}, at::device(at::kCPU).dtype(at::kByte));
226	    uint8_t *data = lut.data_ptr<uint8_t>();
227	    for (uint32_t i = 0; i < LUT16_SIZE; i++) {
228	        uint16_t val = static_cast<uint16_t>(i); // sign bit always 0
229	        uint32_t exp = (val >> fracBitsN) & ((1u << expBitsN) - 1);
230	        uint32_t frac = val & ((1u << fracBitsN) - 1);
231	        uint32_t fp32Bits = 0u;
232	        if (exp == 0) {
233	            // Subnormal: no implicit leading 1; normalize by finding the leading 1 in frac.
234	            if (frac == 0) {
235	                fp32Bits = 0u;
236	            } else {
237	                // p: position of leading 1 bit; __builtin_clz is UB for 0, guarded above.
238	                uint32_t p = 31u - static_cast<uint32_t>(__builtin_clz(frac)); // 31: uint32_t位数-1
239	                // fp32Exp = (1 - expBias) + (p - fracBitsN) + 127
240	                int32_t fp32Exp = static_cast<int32_t>(p) - static_cast<int32_t>(fracBitsN) -
241	                                  static_cast<int32_t>(expBias - 1u) + 127; // 127: FP32指数偏置
242	                uint32_t fp32Frac = (frac & ((1u << p) - 1u)) << (23u - p); // 23: FP32尾数位数
243	                fp32Bits = (fp32Exp > 0) ? ((static_cast<uint32_t>(fp32Exp) << 23) | fp32Frac) : 0u; // 23: FP32尾数位数
244	            }
245	        } else {
246	            // exp 全 1 表示 Inf/NaN：必须显式映射到 FP32 exp=255，
247	            // 否则 FP16 的 exp=31 会被加上 (127-15)=112 偏置变为 143，丢掉特殊值语义。
248	            uint32_t expMaxN = (1u << expBitsN) - 1;
249	            uint32_t expFp32 = (exp == expMaxN) ? 255u : (exp + (127u - expBias)); // 255/127: FP32指数最大值/偏置
250	            fp32Bits = (expFp32 << 23) | (frac << (23u - fracBitsN));              // 23: FP32尾数位数
251	        }
252	        data[i] = HostFp32MagnitudeToHif8(fp32Bits);                               // magnitude only, no sign
253	    }
254	    return lut;
255	}
256	
257	// ── Torch binding ──────────────────────────────────────────────────────────────
258	
259	static uint32_t GetAivCoreNum() {
260	    auto *platform = platform_ascendc::PlatformAscendCManager::GetInstance();
261	    if (platform == nullptr)
262	        return 32u;          // 32: 默认AIV核数
263	    uint32_t n = platform->GetCoreNumAiv();
264	    return n > 0u ? n : 32u; // 32: 默认AIV核数
265	}
266	
267	static uint32_t GetUbSizeBytes() {
268	    auto *platform = platform_ascendc::PlatformAscendCManager::GetInstance();
269	    if (platform == nullptr)
270	        return 256u * 1024u; // 256KB: 默认UB大小
271	    uint64_t ub = 0;
272	    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub);
273	    return ub > 0u ? static_cast<uint32_t>(ub) : 256u * 1024u; // 256KB: 默认UB大小
274	}
275	
276	static uint32_t ComputeMaxTileLength(uint32_t ubBytes, bool isEncode) {
277	    uint32_t lutBytes = isEncode ? LUT16_SIZE : (LUT8_SIZE * 2u);
278	    // UB 连 LUT 都放不下，硬件配置异常
279	    TORCH_CHECK(ubBytes > lutBytes, "UB too small to hold LUT");
280	    // 每个元素占 3 字节 UB：encode/decode 的 input + output 之和（FP16/BF16 是 2B，HiF8 是 1B）。
281	    // 单缓冲（TQue depth=1, InitBuffer num=1）—— 标量循环主导，MTE/Compute 重叠收益为 0。
282	    uint32_t maxTile = (ubBytes - lutBytes) / 3u;
283	    // UB 剩余空间不足一个最小 tile（32 元素），硬件配置异常
284	    TORCH_CHECK(maxTile >= 32u, "UB too small to hold minimum tile");
285	    maxTile = std::min(maxTile, 65536u); // A3 UB 实测最大可用 tile
286	    // ≥ 32768 时对齐到 32768 的整数倍，使 CopyIn 大块走 Case B（{n, 32768}），
287	    // 避免 DataCopyParams.blockLen(uint16_t) 溢出
288	    if (maxTile >= 32768u) { // 32768: tile对齐阈值，避免blockLen溢出
289	        return (maxTile / 32768u) * 32768u;
290	    }
291	    return std::max((maxTile / 32u) * 32u, 32u); // 小 tile 对齐到 32（向量指令粒度）
292	}
293	
294	static uint32_t ComputeNumBlocks(uint64_t totalElements, uint32_t maxBlocks, uint32_t minPerCore) {
295	    TORCH_CHECK(minPerCore > 0u, "minPerCore must be positive");
296	    uint64_t idealBlocks64 = totalElements / minPerCore;
297	    idealBlocks64 = std::min(idealBlocks64, static_cast<uint64_t>(maxBlocks));
298	    uint32_t idealBlocks = static_cast<uint32_t>(idealBlocks64);
299	    return std::max(idealBlocks, 1u);
300	}
301	
302	static void ValidateInput(const at::Tensor &input, int64_t castMode) {
303	    TORCH_CHECK(castMode >= FP16_TO_HIF8 && castMode <= HIF8_TO_BF16, "castMode must be in [0, 3]");
304	    TORCH_CHECK(input.device().type() == c10::DeviceType::PrivateUse1, "input must be on NPU device");
305	    if (castMode == FP16_TO_HIF8)
306	        TORCH_CHECK(input.dtype() == at::kHalf, "FP16_TO_HIF8 requires half input");
307	    if (castMode == BF16_TO_HIF8)
308	        TORCH_CHECK(input.dtype() == at::kBFloat16, "BF16_TO_HIF8 requires bfloat16 input");
309	    if (castMode >= HIF8_TO_FP16)
310	        TORCH_CHECK(input.dtype() == at::kByte, "decode modes require uint8 input");
311	}
312	
313	static at::Tensor AllocateOutput(const at::Tensor &inputContiguous, int64_t castMode) {
314	    if (castMode <= BF16_TO_HIF8)
315	        return at::empty(inputContiguous.sizes(), inputContiguous.options().dtype(at::kByte));
316	    if (castMode == HIF8_TO_FP16)
317	        return at::empty(inputContiguous.sizes(), inputContiguous.options().dtype(at::kHalf));
318	    return at::empty(inputContiguous.sizes(), inputContiguous.options().dtype(at::kBFloat16));
319	}
320	
321	static HiFloat8CastTilingData BuildTilingData(int64_t totalElements, int64_t castMode, bool isEncode) {
322	    uint32_t ubBytes = GetUbSizeBytes();
323	    uint32_t maxBlocks = GetAivCoreNum();
324	    uint32_t maxTileLen = ComputeMaxTileLength(ubBytes, isEncode);
325	
326	    constexpr uint32_t MIN_PER_CORE_ENCODE = 4096u;
327	    constexpr uint32_t MIN_PER_CORE_DECODE = 2048u;
328	    uint32_t minPerCore = isEncode ? MIN_PER_CORE_ENCODE : MIN_PER_CORE_DECODE;
329	
330	    uint32_t numBlocks = ComputeNumBlocks(totalElements, maxBlocks, minPerCore);
331	    uint64_t numPerCore = static_cast<uint64_t>(totalElements / numBlocks);
332	    uint64_t tailNum = static_cast<uint64_t>(totalElements - numPerCore * (numBlocks - 1));
333	    uint32_t tileLength =
334	        static_cast<uint32_t>(std::min(static_cast<uint64_t>(maxTileLen), static_cast<uint64_t>(numPerCore)));
335	
336	    return {numBlocks, static_cast<uint64_t>(totalElements), numPerCore, tailNum, static_cast<uint32_t>(castMode),
337	        tileLength};
338	}
339	
340	static at::Tensor UploadTilingToDevice(const HiFloat8CastTilingData &tilingHost, const at::Tensor &refTensor) {
341	    at::Tensor tilingTensor = at::empty({sizeof(HiFloat8CastTilingData)}, at::device(at::kCPU).dtype(at::kByte));
342	    errno_t ret = memcpy_s(tilingTensor.data_ptr(), tilingTensor.nbytes(), &tilingHost, sizeof(HiFloat8CastTilingData));
343	    TORCH_CHECK(ret == EOK, "copy tiling data to host tensor failed, memcpy_s ret: ", ret);
344	    return tilingTensor.to(refTensor.device());
345	}
346	
347	// LUT 在首次使用时构建并搬到 device，进程生命周期内每种 castMode 只构建一次。
348	static uint8_t *GetOrBuildLutOnDevice(int64_t castMode, const at::Tensor &refTensor) {
349	    static std::mutex lutMutex;
350	    static std::map<std::pair<int64_t, int64_t>, at::Tensor> lutCache;
351	
352	    int64_t deviceIndex = static_cast<int64_t>(refTensor.device().index());
353	    auto key = std::make_pair(deviceIndex, castMode);
354	    std::lock_guard<std::mutex> guard(lutMutex);
355	    auto it = lutCache.find(key);
356	    if (it != lutCache.end()) {
357	        return reinterpret_cast<uint8_t *>(it->second.data_ptr());
358	    }
359	
360	    at::Tensor lut;
361	    switch (castMode) {
362	        case FP16_TO_HIF8: lut = BuildLut16Cpu(FP16_TO_HIF8).to(refTensor.device()); break;
363	        case BF16_TO_HIF8: lut = BuildLut16Cpu(BF16_TO_HIF8).to(refTensor.device()); break;
364	        case HIF8_TO_FP16: lut = BuildLut8Cpu(HIF8_TO_FP16).to(refTensor.device()); break;
365	        default: // HIF8_TO_BF16
366	            lut = BuildLut8Cpu(HIF8_TO_BF16).to(refTensor.device());
367	            break;
368	    }
369	    auto result = lutCache.emplace(key, std::move(lut));
370	    return reinterpret_cast<uint8_t *>(result.first->second.data_ptr());
371	}
372	
373	namespace AscendKernel {
374	
375	at::Tensor Hifloat8CastTorch(const at::Tensor &input, int64_t castMode) {
376	    ValidateInput(input, castMode);
377	
378	    auto inputContiguous = input.contiguous();
379	    int64_t totalElements = inputContiguous.numel();
380	    TORCH_CHECK(totalElements > 0, "input tensor must not be empty");
381	
382	    at::Tensor output = AllocateOutput(inputContiguous, castMode);
383	    bool isEncode = (castMode <= BF16_TO_HIF8);
384	
385	    HiFloat8CastTilingData tilingHost = BuildTilingData(totalElements, castMode, isEncode);
386	    at::Tensor tilingDevice = UploadTilingToDevice(tilingHost, input);
387	    uint8_t *lutGm = GetOrBuildLutOnDevice(castMode, input);
388	
389	    auto aclStream = c10_npu::getCurrentNPUStream().stream(true);
390	    hifloat8_cast_kernel_lut(tilingHost.blockNum, nullptr, aclStream,
391	        reinterpret_cast<uint8_t *>(inputContiguous.data_ptr()), reinterpret_cast<uint8_t *>(output.data_ptr()),
392	        reinterpret_cast<uint8_t *>(tilingDevice.data_ptr()), lutGm);
393	
394	    return output;
395	}
396	
397	} // namespace AscendKernel
